  <script>
    const search = document.querySelector('#search');
    const cards = [...document.querySelectorAll('.card')];
    const count = document.querySelector('#count');
    const empty = document.querySelector('#empty');
    const mode = new URLSearchParams(location.search).get('tags');
    if (mode === 'chips') document.body.classList.add('mode-chips');
    if (mode === 'sidebar') document.body.classList.add('mode-sidebar');
    let selectedTag = 'all';
    function filterCards() {
      const query = search.value.trim().toLocaleLowerCase();
      let shown = 0;
      cards.forEach(card => {
        const textMatch = card.dataset.search.toLocaleLowerCase().includes(query);
        const tagMatch = selectedTag === 'all' || card.dataset.tags.split(' ').includes(selectedTag);
        const match = textMatch && tagMatch;
        card.style.display = match ? '' : 'none';
        if (match) shown++;
      });
      count.textContent = `${shown} bookmark${shown === 1 ? '' : 's'}`;
      empty.style.display = shown ? 'none' : 'block';
    }
    search.addEventListener('input', filterCards);
    document.querySelectorAll('.tag-filter').forEach(button => button.addEventListener('click', () => {
      selectedTag = button.dataset.tag;
      document.querySelectorAll('.tag-filter').forEach(item => item.classList.toggle('active', item.dataset.tag === selectedTag));
      filterCards();
    }));
